#include <iostream>
#include <string>
using namespace std;

class Bentuk {
public:
    virtual ~Bentuk() {
    }

    virtual string nama() const {
        return "bentuk";
    }

    virtual int luas() const {
        return 0;
    }

    virtual void skala(int) {
    }
};

class Persegi : public Bentuk {
private:
    int sisi;

public:
    Persegi(int s) : sisi(s) {
    }

    string nama() const override {
        return "persegi";
    }

    int luas() const override {
        return sisi * sisi;
    }

    void skala(int k) override {
        sisi *= k;
    }
};

class PersegiPanjang : public Bentuk {
private:
    int panjang;
    int lebar;

public:
    PersegiPanjang(int p, int l) : panjang(p), lebar(l) {
    }

    string nama() const override {
        return "persegi panjang";
    }

    int luas() const override {
        return panjang * lebar;
    }

    void skala(int k) override {
        panjang *= k;
        lebar *= k;
    }
};

int main() {
    Bentuk *daftar[10];
    auto banyak = 0;
    string kata;
    while (cin >> kata) {
        if (kata == "selesai") {
            break;
        }
        if (kata == "persegi" || kata == "panjang") {
            if (kata == "persegi") {
                int s;
                cin >> s;
                daftar[banyak] = new Persegi(s);
            } else {
                int p, l;
                cin >> p >> l;
                daftar[banyak] = new PersegiPanjang(p, l);
            }
            banyak++;
            cout << "Bentuk " << banyak << " ditambahkan" << endl;
            continue;
        }
        int nomor;
        cin >> nomor;
        auto ada = nomor >= 1 && nomor <= banyak && daftar[nomor - 1] != nullptr;
        if (kata == "skala") {
            int faktor;
            cin >> faktor;
            if (ada) {
                daftar[nomor - 1]->skala(faktor);
                cout << "Bentuk " << nomor << ": " << daftar[nomor - 1]->nama() << " " << daftar[nomor - 1]->luas() << endl;
            }
        } else if (ada) {
            delete daftar[nomor - 1];
            daftar[nomor - 1] = nullptr;
            cout << "Bentuk " << nomor << " dihapus" << endl;
        }
        if (!ada) {
            cout << "Tidak ada bentuk " << nomor << endl;
        }
    }
    auto total = 0;
    for (int k = 0; k < banyak; k++) {
        if (daftar[k] != nullptr) {
            cout << k + 1 << ". " << daftar[k]->nama() << " " << daftar[k]->luas() << endl;
            total += daftar[k]->luas();
            delete daftar[k];
        }
    }
    cout << "Total luas: " << total << endl;
    return 0;
}

id.statement:
Sebuah ekspresi hitung bisa disimpan sebagai **pohon**: daunnya angka, dan tiap simpul dalam adalah satu operasi dengan dua anak. Setiap simpul tahu cara menghitung nilainya dan cara mencetak dirinya — dan untuk itu ia cukup meminta anak-anaknya melakukan hal yang sama.

Susun hierarkinya:

- `Simpul` — `virtual int nilai() const`, `virtual void cetak() const`, destruktor virtual;
- `Angka` turunan `Simpul` — menyimpan satu bilangan;
- `Biner` turunan `Simpul` — memegang `Simpul *kiri` dan `Simpul *kanan`; destruktornya menghapus keduanya; punya `virtual char simbol() const`; `cetak()` mencetak `(<kiri> <simbol> <kanan>)`;
- `Tambah`, `Kurang`, `Kali` turunan `Biner` — menimpa `simbol()` dan `nilai()`.

Masukan berupa ekspresi dalam **notasi awalan** (operator ditulis sebelum kedua operandnya), tiap token dipisah spasi; operandnya angka satu digit. Fungsi rekursif `Simpul *baca()` membaca satu token: bila operator, ia membaca dua subpohon lalu membuat simpulnya; bila angka, ia membuat `Angka`.

Cetak ekspresi itu dalam notasi biasa dengan kurung lengkap, lalu ` = ` dan nilainya. Akhiri dengan `delete akar`.

Contoh: `+ 3 * 4 5` → `(3 + (4 * 5)) = 23`; `- 2 9` → `(2 - 9) = -7`; `7` → `7 = 7`.

**Kode harus memuat class turunan dan fungsi anggota `virtual`**: keluaran yang benar tanpa itu hanya mendapat setengah nilai.

en.statement:
An arithmetic expression can be kept as a **tree**: its leaves are numbers, and every inner node is one operation with two children. Each node knows how to compute its value and how to print itself — and for that it only asks its children to do the same.

Build the hierarchy:

- `Simpul` (node) — `virtual int nilai() const` (value), `virtual void cetak() const`, a virtual destructor;
- `Angka` (number) derived from `Simpul` — keeps one number;
- `Biner` (binary) derived from `Simpul` — holds `Simpul *kiri` (left) and `Simpul *kanan` (right); its destructor deletes both; it has `virtual char simbol() const`; `cetak()` prints `(<left> <symbol> <right>)`;
- `Tambah`, `Kurang`, `Kali` derived from `Biner` — override `simbol()` and `nilai()`.

The input is an expression in **prefix notation** (the operator is written before its two operands), tokens separated by spaces; operands are single digits. A recursive function `Simpul *baca()` reads one token: for an operator it reads two subtrees and then makes the node; for a digit it makes an `Angka`.

Print the expression in ordinary notation, fully parenthesised, then ` = ` and its value. Finish with `delete akar` (the root).

Examples: `+ 3 * 4 5` → `(3 + (4 * 5)) = 23`; `- 2 9` → `(2 - 9) = -7`; `7` → `7 = 7`.

**The code must contain a derived class and a `virtual` member function**: correct output without them gets only half the marks.

