#include <iostream>
#include <string>
using namespace std;

int mutlak(int x) {
    if (x < 0) {
        return -x;
    }
    return x;
}

int arah(int x) {
    if (x > 0) {
        return 1;
    }
    if (x < 0) {
        return -1;
    }
    return 0;
}

class Bidak {
public:
    virtual ~Bidak() {
    }

    virtual char huruf() const {
        return '?';
    }

    virtual bool bolehLangkah(int, int) const {
        return false;
    }

    virtual bool melompat() const {
        return false;
    }
};

class Benteng : public Bidak {
public:
    char huruf() const override {
        return 'B';
    }

    bool bolehLangkah(int db, int dk) const override {
        return db == 0 || dk == 0;
    }
};

class Gajah : public Bidak {
public:
    char huruf() const override {
        return 'G';
    }

    bool bolehLangkah(int db, int dk) const override {
        return mutlak(db) == mutlak(dk);
    }
};

class Kuda : public Bidak {
public:
    char huruf() const override {
        return 'K';
    }

    bool bolehLangkah(int db, int dk) const override {
        return mutlak(db) * mutlak(dk) == 2;
    }

    bool melompat() const override {
        return true;
    }
};

class Raja : public Bidak {
public:
    char huruf() const override {
        return 'R';
    }

    bool bolehLangkah(int db, int dk) const override {
        return mutlak(db) <= 1 && mutlak(dk) <= 1;
    }
};

int main() {
    Bidak *papan[9][9];
    for (int b = 1; b <= 8; b++) {
        for (int k = 1; k <= 8; k++) {
            papan[b][k] = nullptr;
        }
    }
    int n;
    cin >> n;
    for (int j = 0; j < n; j++) {
        string jenis;
        int b, k;
        cin >> jenis >> b >> k;
        if (jenis == "benteng") {
            papan[b][k] = new Benteng;
        } else if (jenis == "gajah") {
            papan[b][k] = new Gajah;
        } else if (jenis == "kuda") {
            papan[b][k] = new Kuda;
        } else {
            papan[b][k] = new Raja;
        }
    }
    int m;
    cin >> m;
    for (int j = 0; j < m; j++) {
        int b1, k1, b2, k2;
        cin >> b1 >> k1 >> b2 >> k2;
        Bidak *bidak = papan[b1][k1];
        if (bidak == nullptr) {
            cout << "Kosong" << endl;
            continue;
        }
        auto db = b2 - b1;
        auto dk = k2 - k1;
        if ((db == 0 && dk == 0) || !bidak->bolehLangkah(db, dk)) {
            cout << "Langkah tidak sah" << endl;
            continue;
        }
        auto terhalang = false;
        if (!bidak->melompat()) {
            auto b = b1 + arah(db);
            auto k = k1 + arah(dk);
            while (b != b2 || k != k2) {
                if (papan[b][k] != nullptr) {
                    terhalang = true;
                }
                b += arah(db);
                k += arah(dk);
            }
        }
        if (terhalang) {
            cout << "Terhalang" << endl;
        } else if (papan[b2][k2] != nullptr) {
            cout << "Petak terisi" << endl;
        } else {
            papan[b2][k2] = bidak;
            papan[b1][k1] = nullptr;
            cout << bidak->huruf() << " ke " << b2 << " " << k2 << endl;
        }
    }
    for (int b = 1; b <= 8; b++) {
        for (int k = 1; k <= 8; k++) {
            if (papan[b][k] == nullptr) {
                cout << ".";
            } else {
                cout << papan[b][k]->huruf();
                delete papan[b][k];
            }
        }
        cout << endl;
    }
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

class Tugas {
protected:
    string nama;

public:
    Tugas(const string &n) : nama(n) {
    }

    virtual ~Tugas() {
    }

    string getNama() const {
        return nama;
    }

    virtual bool waktunya(int) const {
        return true;
    }

    virtual void jalan() {
    }

    virtual bool tuntas() const {
        return false;
    }
};

class Sekali : public Tugas {
private:
    int kapan;
    bool sudah = false;

public:
    Sekali(const string &n, int t) : Tugas(n), kapan(t) {
    }

    bool waktunya(int t) const override {
        return t == kapan;
    }

    void jalan() override {
        sudah = true;
    }

    bool tuntas() const override {
        return sudah;
    }
};

class Berulang : public Tugas {
protected:
    int selang;

public:
    Berulang(const string &n, int s) : Tugas(n), selang(s) {
    }

    bool waktunya(int t) const override {
        return t % selang == 0;
    }
};

class Terbatas : public Berulang {
private:
    int sisa;

public:
    Terbatas(const string &n, int s, int kali) : Berulang(n, s), sisa(kali) {
    }

    void jalan() override {
        sisa--;
    }

    bool tuntas() const override {
        return sisa == 0;
    }
};

int main() {
    int n, lama;
    cin >> n >> lama;
    Tugas *daftar[6];
    for (int k = 0; k < n; k++) {
        string jenis, nama;
        cin >> jenis >> nama;
        if (jenis == "sekali") {
            int t;
            cin >> t;
            daftar[k] = new Sekali(nama, t);
        } else if (jenis == "berulang") {
            int s;
            cin >> s;
            daftar[k] = new Berulang(nama, s);
        } else if (jenis == "terbatas") {
            int s, kali;
            cin >> s >> kali;
            daftar[k] = new Terbatas(nama, s, kali);
        } else {
            daftar[k] = new Tugas(nama);
        }
    }
    for (int t = 1; t <= lama; t++) {
        for (int k = 0; k < n; k++) {
            if (daftar[k] == nullptr || !daftar[k]->waktunya(t)) {
                continue;
            }
            daftar[k]->jalan();
            cout << t << ": " << daftar[k]->getNama() << endl;
            if (daftar[k]->tuntas()) {
                cout << t << ": " << daftar[k]->getNama() << " selesai" << endl;
                delete daftar[k];
                daftar[k] = nullptr;
            }
        }
    }
    auto tersisa = 0;
    for (int k = 0; k < n; k++) {
        if (daftar[k] != nullptr) {
            tersisa++;
            delete daftar[k];
        }
    }
    cout << "Tersisa: " << tersisa << endl;
    return 0;
}
